import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in); int n=s.nextInt(); int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=s.nextInt(); int x=s.nextInt(); int l=0,r=n; while(l<r){int m=(l+r)/2; if(a[m]<x)l=m+1; else r=m;} int first=(l<n&&a[l]==x)?l:-1; l=0;r=n; while(l<r){int m=(l+r)/2; if(a[m]<=x)l=m+1; else r=m;} int last=first==-1?-1:l-1; System.out.println(first+" "+last);
  }
}

